    });

    return db.workflowArtifact.findUniqueOrThrow({
      where: { id: artifact.id },
      include: { workflow: true, run: true }
    }) as Promise<FullArtifact>;
  };

  return {
    default: defaultArtifact,
    input,
    output,
    withRun
  };
};

